cat > /tmp/check5.sing << 'EOF'
ring R = 0,(x1,x2,x3,x4,x5,x6),dp;
ideal I = x2*x4 + x3*x6,
          x3*x5 + x1*x6,
          x1*x2 - x2*x5 + x3*x5 - x5*x6,
          x2*x3 + x2*x4 + x2*x6 + x6^2,
          x3^2 + x3*x4 + x3*x6 - x4*x6,
          x1*x3 + x1*x4 + x4*x5 + x1*x6;

// Check which triples of generators form a regular sequence
// by checking if their ideal has height 3
ideal J;
for (int i=1; i<=6; i++) {
  for (int j=i+1; j<=6; j++) {
    for (int k=j+1; k<=6; k++) {
      J = I[i], I[j], I[k];
      J = std(J);
      if (dim(J)==3) {
        "triple", i, j, k, "has height", 6-dim(J);
      }
    }
  }
}
EOF
singular /tmp/check5.sing 2>&1 | grep -E "triple|height"

