cat > /tmp/final_check.sing << 'EOF'
ring R = 0,(x1,x2,x3,x4,x5,x6),dp;
ideal I = x2*x4 + x3*x6,
          x3*x5 + x1*x6,
          x1*x2 - x2*x5 + x3*x5 - x5*x6,
          x2*x3 + x2*x4 + x2*x6 + x6^2,
          x3^2 + x3*x4 + x3*x6 - x4*x6,
          x1*x3 + x1*x4 + x4*x5 + x1*x6;
I = std(I);

// Hilbert series
"Hilbert series numerator:";
hilb(I,1);

// Multiplicity (degree)
"Multiplicity:";
mult(I);

// Check if I is prime (already done, but confirm)
"Is I radical?";
ideal radI = radical(I);
size(reduce(I, radI));
size(reduce(radI, I));

// Verify the resolution one more time
resolution F = mres(I,0);
"Betti:";
betti(F);
"pd (= size-1):", size(F)-1;

// Verify minimality: all entries of maps are in maximal ideal
matrix d1 = F[1];
matrix d2 = F[2];
matrix d3 = F[3];
"Max constant in d1:", jet(d1, 0);
"Max constant in d2:", jet(d2, 0);
"Max constant in d3:", jet(d3, 0);
EOF
